import heapq


def _resolver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=name_order == "descending")
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[None] + [row["version"] for row in packages[name]]
               for name in names]
    best_vector = None
    best_versions = None

    for selection in product(*choices):
        versions = {name: version for name, version in zip(names, selection)
                    if version is not None}
        if any(not (bounds[0] <= versions.get(name, -1) <= bounds[1])
               for name, bounds in data["roots"].items()):
            continue
        if any(version in blocked.get(name, []) for name, version in versions.items()):
            continue
        if any(name in versions and versions[name] != pin for name, pin in pins.items()):
            continue

        rows = {name: next((row for row in packages[name]
                            if row["version"] == version), None)
                for name, version in versions.items()}
        graph = {name: [] for name in versions}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = versions.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be exactly the closure of the roots.
        closure = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(graph.get(name, []))
        if closure != set(versions):
            continue

        active, done = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            done.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        vector = tuple(versions.get(name, -1) for name in names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best_versions = versions

    return ({"versions": best_versions} if best_versions is not None
            else {"error": "unsatisfiable"})


def _build_resolver(preference, name_order):
    return lambda data: _resolver(data, preference, name_order)


def _build_ledger():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data.get("rounding", "floor")
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_quota_intervals():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        k = data["k"]
        for group, bounds in data.get("quotas", {}).items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                return False
        # Unmentioned groups have bounds [0, k], so need no further check.
        timeline = []
        for job in selected:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = peak = 0
        for _, delta in sorted(timeline):  # ends precede starts at equal times
            active += delta
            peak = max(peak, active)
        return peak <= 2

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            if not feasible(subset, data):
                continue
            value = sum(job["value"] for job in subset)
            ids = tuple(sorted(job["id"] for job in subset))
            if (best_value is None or value > best_value or
                    (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_routes():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start = data["source"]
        initial_mask = bit.get(start, 0)
        initial = (start, initial_mask, data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], start, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                for duration, new_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, new_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask,
                                               new_remaining))
        return {"arrival": None}
    return solve


